package auth

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"net/url"
	"strings"
	"testing"

	"github.com/labstack/echo/v5"
)

func TestFetchCertAuth(t *testing.T) {

	kubeSpec := &CertKubeAuth{}

	// Base64-encoded dummy client certificate and key (expired 2019
	// minikube-user fixture) in the cert:key layout the original mock used.
	mockCertAndKey := ":"

	parts := strings.SplitN(mockCertAndKey, ":", 2)
	form := url.Values{}
	form.Set("cert", parts[0])
	form.Set("certKey", parts[1])

	e := echo.New()
	req := httptest.NewRequest(http.MethodPost, "/pp/v1/auth/login/cnsi?cnsi_guid=testGuid&connect_type=kube-cert-auth&system_shared=false", strings.NewReader(form.Encode()))
	req.Header.Set(echo.HeaderContentType, echo.MIMEApplicationForm)

	engineReq := req
	rec := httptest.NewRecorder()
	c := e.NewContext(engineReq, rec)

	kubeCertAuth, err := kubeSpec.extractCerts(c)
	if err != nil {
		t.Fatalf("extractCerts failed: %v", err)
	}

	if kubeCertAuth.Certificate == "" {
		t.Fatal("expected certificate to be extracted")
	}

	if kubeCertAuth.CertificateKey == "" {
		t.Fatal("expected certificate key to be extracted")
	}

	jsonString, err := kubeCertAuth.GetJSON()

	if err != nil {
		t.Fatalf("GetJSON failed: %v", err)
	}

	testKubeCertAuth := &KubeCertificate{}
	err = json.NewDecoder(strings.NewReader(jsonString)).Decode(testKubeCertAuth)
	if err != nil {
		t.Fatalf("failed to decode JSON: %v", err)
	}
	if testKubeCertAuth.Certificate != kubeCertAuth.Certificate {
		t.Error("certificate did not round-trip")
	}
	if testKubeCertAuth.CertificateKey != kubeCertAuth.CertificateKey {
		t.Error("certificate key did not round-trip")
	}
}
